Object.assign(I18N.ko, {"as.li": "리 = 축산차량 방문 기록의 주소 단위인 행정리(예: '전라남도 나주시 봉황면 덕림리'). 리마다 발생 2~4주 전 3주 동안 축산차량이 몇 번 드나들었는지 세고, 그 주에 그 리에서 농장 발생이 있었는지와 비교했습니다. 발생 바로 앞 1주는 의심 신고 뒤 시료채취·방역 차량이 드나드는 기간이라 뺐습니다.", "as.visit.v": "발생 2~4주 전 3주 동안 차량이 {a}회 이상 드나든 리는 {b}인 리보다 발생 위험이 <b>×{rr}</b> (오차 범위 {lo}~{hi}배).", "as.dose": "3주간 방문 횟수 구간별 위험 배수 (방문이 가장 적은 구간 = 1배)", "as.byveh": "차량 유형별 — 그 차량이 많이 드나든 리의 위험 배수 (나머지 리 = 1배)", "as.resp": "참고: 발생 대응 차량(시료채취·방역·사체운반) — 발생이 의심된 뒤 드나드는 경우가 많아 결과일 수 있으므로 합계에서 뺐습니다", "as.vth": "(3주 {n}회 초과)", "as.vth1": "(3주 1회 이상)", "as.vrange": "3주 {a}~{b}회", "as.vmore": "3주 {a}회 이상", "as.v0": "방문 없음", "as.vb0": "없음", "as.vb1": "적음", "as.vb2": "보통", "as.vb3": "많음", "as.vb4": "아주 많음"});

Object.assign(I18N.en, {"as.li": "Village (리) = the address unit of livestock-vehicle visit records (e.g. '전라남도 나주시 봉황면 덕림리'). For each village we count vehicle visits during the 3 weeks from 4 to 2 weeks before, and compare with whether a farm outbreak occurred that week. The week right before is skipped, since sampling and disinfection vehicles arrive after a suspected case.", "as.visit.v": "Villages with {a}+ visits in the 3 weeks (2–4 weeks before) had <b>×{rr}</b> the outbreak risk of villages with {b} (range {lo}–{hi}).", "as.dose": "Risk multiplier by visits in 3 weeks (lowest band = ×1)", "as.byveh": "By vehicle type — villages heavily visited by that type vs the rest", "as.resp": "Reference: response vehicles (sampling, disinfection, carcass) — often arrive after a suspected case, so excluded from the total", "as.vth": "(> {n} in 3 wk)", "as.vth1": "(1+ in 3 wk)", "as.vrange": "{a}–{b} visits", "as.vmore": "{a}+ visits", "as.v0": "No visits", "as.vb0": "none", "as.vb1": "low", "as.vb2": "medium", "as.vb3": "high", "as.vb4": "very high"});

